export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const smooth=(a,b,v)=>{const t=clamp((v-a)/(b-a),0,1);return t*t*(3-2*t);};
export function random(seed=27){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
// x, z, water height, half-width. A carved 3D channel, not an image animation.
export const RIVER=[[-3,-31,10.42,.65],[-6,-27,10.4,.72],[-8,-25,10.36,.75],[-8,-23.5,7.42,.78],[-6,-19,7.4,.84],[-5,-16,7.38,.85],[-3,-12.2,7.35,.88],[-2.2,-11.8,3.42,.93],[2,-9,3.4,.95],[5,-5,3.4,1.02],[4,0,3.38,1.05],[1,2,3.35,1.08],[-1,4.3,.42,1.12],[-4.6,9,.4,1.18],[-4.4,14,.37,1.25],[-.5,21,.35,1.42],[1,26,.34,1.7]];
export function riverAt(x,z){let result={distance:Infinity,y:0,width:1,t:0,index:0};for(let i=0;i<RIVER.length-1;i++){const a=RIVER[i],b=RIVER[i+1],dx=b[0]-a[0],dz=b[1]-a[1],t=clamp(((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz),0,1),distance=Math.hypot(x-a[0]-dx*t,z-a[1]-dz*t);if(distance<result.distance)result={distance,y:a[2]+(b[2]-a[2])*t,width:a[3]+(b[3]-a[3])*t,t,index:i};}return result;}
export function baseHeight(x,z){const lowerRamp=1-smooth(.8,1.7,Math.abs(x+9)),upperRamp=1-smooth(.75,1.6,Math.abs(x+17)),lower=3.05*((1-smooth(2,4.3,z))*(1-lowerRamp)+(1-smooth(1,5,z))*lowerRamp),upper=4*((1-smooth(-12.2,-11.8,z))*(1-upperRamp)+(1-smooth(-16,-11,z))*upperRamp);return .27+lower+upper+3*(1-smooth(-25,-23.5,z))+.055*Math.sin(x*.43)*Math.cos(z*.32);}
export function groundHeight(x,z){const b=baseHeight(x,z),r=riverAt(x,z),carve=1-smooth(r.width*.85,r.width+1.1,r.distance);return b+(Math.min(b,r.y-.25)-b)*carve;}
export const BRIDGES=[{x0:2.7,x1:7.3,z0:-5.85,z1:-4.15,y:4.03},{x0:-7.5,x1:-1.7,z0:9.15,z1:10.85,y:1.08}];
export function walkingHeight(x,z){const base=baseHeight(x,z);for(const b of BRIDGES)if(z>=b.z0&&z<=b.z1&&x>=b.x0-.95&&x<=b.x1+.95){const blend=x<b.x0?smooth(b.x0-.95,b.x0,x):x>b.x1?1-smooth(b.x1,b.x1+.95,x):1;return base+(b.y-base)*blend;}return base;}
