export const HOTSPOTS={church:{title:'钟楼里的风',copy:'轻轻敲一次钟，让山谷替我们记住今天。',action:'让钟声响起',at:[-7.9,7.3,-7.1]},baker:{title:'刚出炉的早晨',copy:'面包师还在门前忙碌。慢一点，生活也会有热乎乎的香气。',action:'跟面包师打个招呼',at:[-9,4,.2]},cheese:{title:'山里的奶酪工坊',copy:'木架上的奶酪，装着这片草坡和整个夏天的味道。',action:'收下一小块奶酪',at:[9.5,4,-1]},cable:{title:'向雪峰慢慢靠近',copy:'坐上缆车，看溪水经过小镇，一直流向有牛羊的草坡。',action:'乘一程缆车',at:[12.8,6,-12]},fountain:{title:'把一个愿望交给山谷',copy:'愿你永远平安、自由。也愿我们，一直有下一片想一起去的山野。',action:'许一个小小的愿望',at:[-2,3.6,-1.5]},flock:{title:'草坡上的小小队伍',copy:'牧羊犬听到了你的招呼。跟着它，一起去看看羊群。',action:'跟小狗去散步',at:[13,.7,7]}};
export function isWalkable(x,z){if(x< -21||x>21||z< -23||z>23)return false;const onBridge=BRIDGES.some(b=>x>=b.x0&&x<=b.x1&&z>=b.z0&&z<=b.z1);const r=riverAt(x,z);if(r.distance<r.width+.22&&!onBridge)return false;for(const b of BUILDINGS)if(Math.abs(x-b.x)<b.w/2+.35&&Math.abs(z-b.z)<b.d/2+.35)return false;if(Math.hypot(x+2,z+1.5)<1.1)return false;return true;}
const STEP=.75,MIN_X=-21,MIN_Z=-22.5,COLS=57,ROWS=61;
function cell(x,z){return[Math.round((x-MIN_X)/STEP),Math.round((z-MIN_Z)/STEP)];}
const point=(x,z)=>({x:MIN_X+x*STEP,z:MIN_Z+z*STEP});
function nearest(x,z){const[c,r]=cell(x,z);for(let ring=0;ring<6;ring++){let best=null,d=Infinity;for(let dx=-ring;dx<=ring;dx++)for(let dz=-ring;dz<=ring;dz++){const nx=c+dx,nz=r+dz;if(nx<0||nz<0||nx>=COLS||nz>=ROWS)continue;const p=point(nx,nz),dist=Math.hypot(x-p.x,z-p.z);if(dist<d&&isWalkable(p.x,p.z)){best=[nx,nz];d=dist;}}if(best)return best;}return null;}
class Heap{constructor(){this.values=[]}push(item){let i=this.values.length;this.values.push(item);while(i){const p=(i-1)>>1;if(this.values[p].f<=item.f)break;this.values[i]=this.values[p];i=p;}this.values[i]=item;}pop(){const top=this.values[0],last=this.values.pop();if(this.values.length){let i=0;while(i*2+1<this.values.length){let n=i*2+1;if(n+1<this.values.length&&this.values[n+1].f<this.values[n].f)n++;if(this.values[n].f>=last.f)break;this.values[i]=this.values[n];i=n;}this.values[i]=last;}return top;}}
export function findPath(start,end){const a=nearest(start.x,start.z),b=nearest(end.x,end.z);if(!a||!b)return[];const size=COLS*ROWS,g=new Float32Array(size).fill(Infinity),parent=new Int32Array(size).fill(-1),closed=new Uint8Array(size),open=new Heap();const idx=(x,z)=>z*COLS+x,finish=idx(...b),first=idx(...a);g[first]=0;open.push({x:a[0],z:a[1],f:0});let found=false;
 while(open.values.length){const n=open.pop(),ni=idx(n.x,n.z);if(closed[ni])continue;closed[ni]=1;if(ni===finish){found=true;break;}const np=point(n.x,n.z);for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++){if(!dx&&!dz)continue;const x=n.x+dx,z=n.z+dz;if(x<0||x>=COLS||z<0||z>=ROWS)continue;const i=idx(x,z),p=point(x,z);if(closed[i]||!isWalkable(p.x,p.z)||Math.abs(walkingHeight(p.x,p.z)-walkingHeight(np.x,np.z))>1.65)continue;if(dx&&dz&&(!isWalkable(np.x+dx*STEP,np.z)||!isWalkable(np.x,np.z+dz*STEP)))continue;const score=g[ni]+Math.hypot(dx,dz);if(score>=g[i])continue;g[i]=score;parent[i]=ni;open.push({x,z,f:score+Math.hypot(x-b[0],z-b[1])});}}
 if(!found)return[];const path=[];for(let i=finish;i!==-1;i=parent[i])path.push(point(i%COLS,Math.floor(i/COLS)));return path.reverse();}
export function patrol(route,time,speed=.65,pause=1.7){const lengths=route.map((p,i)=>Math.hypot(route[(i+1)%route.length][0]-p[0],route[(i+1)%route.length][1]-p[1])/speed+pause),duration=lengths.reduce((a,b)=>a+b,0);const lapTime=((time%duration)+duration)%duration;let t=lapTime;for(let i=0;i<route.length;i++){const a=route[i],b=route[(i+1)%route.length],walk=lengths[i]-pause;if(t<=lengths[i]){const f=clamp(t/walk,0,1),moving=t<walk;return{x:a[0]+(b[0]-a[0])*f,z:a[1]+(b[1]-a[1])*f,moving,yaw:Math.atan2(b[0]-a[0],b[1]-a[1])+(moving?0:Math.sin(t*3)>.3?.12:-.12),lap:Math.floor(time/duration),lapTime,duration};}t-=lengths[i];}return{x:route[0][0],z:route[0][1],moving:false,yaw:0,lap:0};}
export class AlpineState{
 constructor(){this.time=0;this.weather='sun';this.day='morning';this.light=.15;this.targetLight=.15;this.auto=false;this.paused=false;this.walker={x:1,z:15,y:walkingHeight(1,15),vx:0,vz:0,moving:false,yaw:0,path:[]};this.flockCall=0;}
 setWeather(v){if(!['sun','rain','fog','snow'].includes(v))return false;this.weather=v;return true;}
 setDay(v){const levels={morning:.15,noon:.5,evening:1};if(!(v in levels))return false;this.day=v;this.targetLight=levels[v];this.auto=false;return true;}
 walkTo(p){const path=findPath(this.walker,p);if(!path.length)return false;this.walker.path=path;return true;}
 update(dt,input={}){if(this.paused)return;dt=clamp(Number(dt)||0,0,.05);this.time+=dt;if(this.auto)this.targetLight=.5+.5*Math.sin(this.time/55-1.1);this.light+=(this.targetLight-this.light)*(1-Math.exp(-dt*1.1));const w=this.walker;let dx=input.x||0,dz=input.z||0,keyboard=Math.hypot(dx,dz)>.01;if(keyboard)w.path=[];else if(w.path.length){const p=w.path[0],d=Math.hypot(p.x-w.x,p.z-w.z);if(d<.13)w.path.shift();else{dx=(p.x-w.x)/d;dz=(p.z-w.z)/d;}}let len=Math.hypot(dx,dz);if(len>1){dx/=len;dz/=len;}const blend=1-Math.exp(-dt/(len>.01?.1:.15));w.vx+=(dx*2.1-w.vx)*blend;w.vz+=(dz*2.1-w.vz)*blend;const x=w.x+w.vx*dt,z=w.z+w.vz*dt;if(isWalkable(x,w.z))w.x=x;else w.vx=0;if(isWalkable(w.x,z))w.z=z;else w.vz=0;w.y=walkingHeight(w.x,w.z);w.moving=Math.hypot(w.vx,w.vz)>.13;if(w.moving)w.yaw=Math.atan2(w.vx,w.vz);}
}
